    private static var cache: [String: NSImage] = [:]

    static func image(_ key: String) -> NSImage? {
        if let cached = cache[key] { return cached }
        guard let path = paths[key] else { return nil }
        let svg = #"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24"><path fill="black" d=""# + path + #""/></svg>"#
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        cache[key] = image
        return image
    }
}

/// A provider's mark, or its initial when there is none.
struct ProviderMark: View {
    let key: String
    var size: CGFloat = 16

    var body: some View {
        if let image = Marks.image(key) {
            Image(nsImage: image)
                .resizable()
                .renderingMode(.template)
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
        } else {
            Text(Provider(key: key).monogram)
                .font(.system(size: size * 0.8, weight: .bold, design: .rounded))
                .frame(width: size, height: size)
        }
    }
}
